import numpy as np

def feature(item, bins, capacity):
    """Percentile rank of each candidate's post-placement leftover among all candidates: 1 = tightest, -1 = loosest."""
    k = bins.shape[0]
    if k < 2:
        return np.zeros(k, dtype=float)
    left = np.clip(bins - item, 0, capacity)
    order = np.argsort(left, kind='stable')  # ties broken by candidate order
    rank = np.empty(k, dtype=float)
    rank[order] = np.arange(k, dtype=float)
    return 1.0 - 2.0 * rank / (k - 1)

